    private void cancelPause(){if(pauseTask!=null){timer.removeCallbacks(pauseTask);pauseTask=null;}}
    private void endDictation(){cancelPause();dictating=false;endingSpeech=false;if(recognizer!=null){recognizer.cancel();recognizer.destroy();recognizer=null;}if(micButton!=null)micButton.setText("🎙");}
    private void applyVoice(){if(!ttsReady||tts==null)return;String name=prefs.getString("voice"+lang(),"");tts.setLanguage(language());if(!name.isEmpty()&&tts.getVoices()!=null){for(Voice v:tts.getVoices())if(v.getName().equals(name)&&v.getLocale().getLanguage().equals(language().getLanguage())){tts.setVoice(v);break;}}tts.setSpeechRate(prefs.getFloat("rate",1f));}
    private ArrayList<Voice> availableVoices(){ArrayList<Voice> list=new ArrayList<>();if(ttsReady&&tts.getVoices()!=null)for(Voice v:tts.getVoices())if(v.getLocale().getLanguage().equals(language().getLanguage())&&!v.isNetworkConnectionRequired()&&(v.getFeatures()==null||!v.getFeatures().contains("notInstalled")))list.add(v);list.sort(Comparator.comparing((Voice v)->!v.getLocale().getLanguage().equals(language().getLanguage())).thenComparing(v->v.getLocale().toLanguageTag()).thenComparing(Voice::getName));return list;}
    private void schedulePause(){cancelPause();if(!dictating||!prefs.getBoolean("autoSend",false)||partial.trim().isEmpty())return;pauseTask=()->{pauseTask=null;if(!dictating||!inChat||busy)return;endingSpeech=true;final SpeechRecognizer session=recognizer;recognizer.stopListening();timer.postDelayed(()->{if(dictating&&endingSpeech&&recognizer==session){endDictation();sendMessage();}},1800);};timer.postDelayed(pauseTask,prefs.getInt("pause",2000));}
    private void updateDictation(String value){partial=value;internalEdit=true;input.setText((prefix+" "+value).trim());input.setSelection(input.length());internalEdit=false;}

