    @Override public void onCreate(Bundle b) { super.onCreate(b); prefs=getSharedPreferences("garlic", MODE_PRIVATE); profile=Math.max(0,Math.min(2,prefs.getInt("profile",0))); speakReplies=prefs.getBoolean("speak",false); tts=new TextToSpeech(this, x -> runOnUiThread(()->{if(x==TextToSpeech.SUCCESS && tts!=null){ttsReady=true;tts.setLanguage(language());applyVoice();tts.setAudioAttributes(new AudioAttributes.Builder().setUsage(AudioAttributes.USAGE_MEDIA).setContentType(AudioAttributes.CONTENT_TYPE_SPEECH).build());tts.setOnUtteranceProgressListener(new UtteranceProgressListener(){public void onStart(String id){} public void onDone(String id){runOnUiThread(()->{if(id.equals("last-"+speechGeneration))reading=false;});}public void onError(String id){runOnUiThread(()->{if(id.endsWith("-"+speechGeneration)){reading=false;Toast.makeText(MainActivity.this,tr("Sprachausgabe fehlgeschlagen"),Toast.LENGTH_LONG).show();}});}});}})); showChat(); }

